//
// Fixed-input vectors generated by advocatra's
// scripts/generate-vault-fixtures.mjs (the real web implementation),
// hardcoded here. These prove this Swift port is byte-identical to the
// real web implementation where cross-platform interop matters (PBKDF2
// derivation, HKDF derivation, and decrypting ciphertext someone else's
// client produced) — not just internally consistent with itself.
//
// Unwrap/decrypt (not wrap/encrypt) is what's tested against the fixed
// vectors: wrapping/encrypting always uses a fresh random IV in this
// module's public API by design, so there's no injection point to
// reproduce an exact ciphertext byte-for-byte — but correctly decrypting
// real ciphertext the TS implementation produced, using a key this Swift
// code derived independently from the same inputs, is an equally
// rigorous (and simpler) proof of interop.
import CryptoKit
import Foundation
import Testing

@testable import AdvocatraVault

@Suite struct CrossPlatformFixtureTests {
    @Test func passphraseKekDerivationUnwrapsRealWebProducedCiphertext() throws {
        let passphrase = "correct horse battery staple"
        let salt = Data(base64Encoded: "AAECAwQFBgcICQoLDA0ODw==")!
        let iterations = 1000
        let expectedMaterial = Data(base64Encoded: "ZGVmZ2hpamtsbW5vcHFyc3R1dnd4eXp7fH1+f4CBgoM=")!
        let wrapped = Data(base64Encoded: "yMnKy8zNzs/Q0dLTz/SSjHaDWvXKbQ8Uf9XKhM+++0hYQ/F0sfZ74p3DDo9O0DcaY/TLrTeyZbn8KJKY")!

        let bits = PBKDF2.deriveBits(password: Data(passphrase.utf8), salt: salt, iterations: iterations, byteCount: 32)
        let kek = SymmetricKey(data: bits)
        let unwrapped = try VaultKey.unwrap(wrapped: wrapped, kek: kek)
        #expect(unwrapped == expectedMaterial)
    }

    @Test func recoveryKekDerivationUnwrapsRealWebProducedCiphertext() throws {
        let recoveryCode = "C04KV-31VF8-0K0JW-R7NPT-007DW"
        let expectedMaterial = Data(base64Encoded: "ZGVmZ2hpamtsbW5vcHFyc3R1dnd4eXp7fH1+f4CBgoM=")!
        let wrapped = Data(
            base64Encoded: "yMnKy8zNzs/Q0dLTqQW+l0bwtadFEVGmAHORe/xkfHG/Sp67NxrLlbyb49UM/8ZsfUm0INORNWhuptA/"
        )!

        let manifest = VaultManifest(
            vaultId: "vault-1",
            appVersion: "0.1.0",
            createdAt: "2027-01-01T00:00:00Z",
            keyEnvelope: KeyEnvelope(
                version: 1,
                passphrase: PassphraseKeyEnvelope(
                    kdf: "PBKDF2-SHA256",
                    iterations: 1,
                    saltBase64: "AA==",
                    wrappedMasterKeyBase64: "AA=="
                ),
                recovery: RecoveryKeyEnvelope(wrappedMasterKeyBase64: wrapped.base64EncodedString())
            )
        )
        let unwrapped = try VaultAccess.unlockWithRecoveryCode(manifest: manifest, recoveryCode: recoveryCode)
        #expect(unwrapped == expectedMaterial)
    }

    @Test func recordsDataEnvelopeDecryptsRealWebProducedCiphertext() throws {
        let masterKeyMaterial = Data(base64Encoded: "ZGVmZ2hpamtsbW5vcHFyc3R1dnd4eXp7fH1+f4CBgoM=")!
        let envelope = EncryptedEnvelope(
            iv: "CgsMDQ4PEBESExQV",
            ciphertext: "/HxL73E1vlO8J01yh3MJWjLuHZiRCeFsFVOh9CflmohUpwpp+7RvkH0p5xj1XGBq+yY8IUS/Nq80p1rz",
            aad: EnvelopeAad(vaultId: "vault-1", purpose: .records, schemaVersion: 1)
        )
        let key = DataKey.derive(masterKeyMaterial: masterKeyMaterial, purpose: .records)
        let plaintext = try Envelope.decrypt(
            envelope,
            key: key,
            expectedAad: EnvelopeAad(vaultId: "vault-1", purpose: .records, schemaVersion: 1)
        )
        #expect(String(data: plaintext, encoding: .utf8) == #"{"taxpayers":[],"matters":[],"documents":[]}"#)
    }
}
